#!/bin/bash
# ===========================================================================
# DEPLOY_v2_fix2 — إصلاح الأعطال الثلاثة التي رصدتها البوابة + إعادة الاختبار
#   D1 تثبيت البوابات الحتمية (استعادة m92/m553/m532)
#   D2 سقف لكل طبقة (الأحكام والنماذج لا تلتهم حصة التشريع)
#   D3 إحياء الكشف الزمني (كان ميتًا — حالة م167)
# لا تفعيل إنتاج، ولا مساس بـapp.py الحي.
# الاستعمال: احفظه ملفًا ثم  bash DEPLOY_v2_fix2.sh
# ===========================================================================
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2fix2.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2fix2.b64 > /tmp/v2fix2.tgz || { echo "B64_FAIL"; exit 1; }
[ -f mcp/server.py ] && cp mcp/server.py "mcp/server.py.bak_$(date +%s)"
tar xzf /tmp/v2fix2.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
echo "الإصلاح وُضع. app.py لم يُمَس."
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/retrieval_layer_validate.py > /tmp/v2val2.log 2>&1 &
disown
echo "بدأت بوابة الانحدار. تابع:  tail -f /tmp/v2val2.log"
